func canCompleteCircuit(gas []int, cost []int) int {
	total, tank, start := 0, 0, 0

	for i := 0; i < len(gas); i++ {
		diff := gas[i] - cost[i]
		total += diff
		tank += diff
		if tank < 0 {
			start = i + 1
			tank = 0
		}
	}

	if total >= 0 {
		return start
	}
	return -1
}

