class Solution:
    def canCompleteCircuit(self, gas: List[int], cost: List[int]) -> int:
        total = 0
        tank = 0
        start = 0

        for i in range(len(gas)):
            diff = gas[i] - cost[i]
            total += diff
            tank += diff
            if tank < 0:
                start = i + 1
                tank = 0

        return start if total >= 0 else -1

impl Solution {
  pub fn can_complete_circuit(gas: Vec<i32>, cost: Vec<i32>) -> i32 {
    let mut total = 0;
    let mut tank = 0;
    let mut start = 0;

    for i in 0..gas.len() {
      let diff = gas[i] - cost[i];
      total += diff;
      tank += diff;
      if tank < 0 {
        start = i as i32 + 1;
        tank = 0;
      }
    }

    if total >= 0 {
      start
    } else {
      -1
    }
  }
}

